create table if not exists public.subscribers(id bigint generated by default as identity primary key,email text not null unique,subscribed boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create table if not exists public.enrollments(id bigint generated by default as identity primary key,name text not null,class_name text not null,email text not null,created_at timestamptz not null default now());alter table public.subscribers enable row level security;alter table public.enrollments enable row level security;